\section{The Category of C*-algebras}
\begin{definition}
The category $\mathcal{C}$ whose objects are $C^*$-algebras and whose morphisms are $*$-homomorphisms is called the \emph{category of $C^*$-algebras} or the $C^*$-algebra category.
\end{definition}

\begin{definition}
Let $\mathcal{A}, \mathcal{B}$ be two \PMlinkname{C*-algebras}{CAlgebra3}. Then a \emph{$*$-homomorphism}
$\phi_*:\mathcal{A} \longrightarrow \mathcal{B}$ is defined as a C*-algebra homomorphism
$\phi:\mathcal{A} \to \mathcal{B}$ which respects involutions, that is:

$$\phi(a^{*_{\mathcal{A}}}) = \phi(a)^{*_{\mathcal{B}}},\quad\mbox{ for any } a \in \mathcal{A}.$$

\end{definition}


{\em Note:}
If `by abuse of notation' one uses $*$ to denote both $*_{\mathcal{A}}$ and $*_{\mathcal{B}}$,
then any $*$-homomorphism $\phi$ commutes with $*$, i.e., $\phi*=*\phi$.

{\bf Remark:}
Note that homomorphisms between $C^*$-algebras are
\PMlinkname{automatically continuous}{ContinuousLinearMapping}.


\begin{thebibliography}{9}

\bibitem{KJ97}
Kustermans, J., C*-algebraic Quantum Groups arising from Algebraic Quantum
Groups, Ph.D. Thesis, K.U.Leuven, 1997.

\bibitem{SAJL97}
Sheu, A.J.L., Compact Quantum Groups and Groupoid C*-Algebras, J. Funct.
Analysis 144 (1997), 371-393.

\end{thebibliography}
